; Status:  confirmed
; ---------------------------------------------------------------------------
Projectile_Straight_Bank1:
    lda     #$FE                    ; $9639  Y velocity -2, so that the
    sta     objYVelocity+7,x        ; $963B  +2 below leaves it at 0

; ---------------------------------------------------------------------------
; Projectile_Falling_Bank1
;
