; In:      x = projectile index
; Status:  confirmed
; ---------------------------------------------------------------------------
Projectile_Bubble_Bank1:
    ldy     #$04                    ; $9647  1/4 px/frame right,
    inc     projectileTimer,x       ; $9649
    lda     projectileTimer,x       ; $964C
    and     #$10                    ; $964F
    beq     @setSpeed               ; $9651
    ldy     #$FC                    ; $9653  or left, every other 16 frames

@setSpeed:
