    jsr     Enemy_MoveX             ; $98E0
    pla                             ; $98E3
    sta     objXVelocity+1,x        ; $98E4  back to the normal speed
    ; Turn toward Link when he is on its level, at most every 160 frames.
    lda     objY                    ; $98E6  Link's Y...
    clc                             ; $98E8
