    sta     temp1                   ; $9D2F
    pla                             ; $9D31
    tay                             ; $9D32
    ldx     temp13                  ; $9D33
    jsr     Sprite_DrawEnemyPairKeepX ; $9D35  the spear
    lda     enemyScratch            ; $9D38
    clc                             ; $9D3B
